const pages=[['home','Visão geral','⌂'],['apk','APK Lab','▣'],['dev','Dev Studio','⌘'],['ai','Programar com IA','✳'],['ai-config','Configuração de IA','⚙'],['chat-ia','Chat IA','◈'],['codex','Codex CLI','⌘'],['terminal','Terminal Center','>_'],['security','Security Lab','⌁'],['system','System Monitor','◉'],['modules','Módulos','▦'],['history','Histórico','≡']];
const paths={home:'<path d="m3 10 9-7 9 7v10h-6v-6H9v6H3z"/>',apk_lab:'<path d="m12 3 8 4.5v9L12 21l-8-4.5v-9z"/>',dev_studio:'<path d="m8 8-4 4 4 4M16 8l4 4-4 4M14 5l-4 14"/>',ai_center:'<path d="m12 3 2 6 6 2-6 2-2 6-2-6-6-2 6-2z"/>',terminal:'<path d="m4 17 6-6-6-6M12 19h8"/>',netscope:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a15 15 0 0 1 0 18"/>',system_monitor:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8M12 17v4"/>',modules:'<rect x="3" y="3" width="8" height="8"/><rect x="13" y="3" width="8" height="8"/><rect x="3" y="13" width="8" height="8"/><rect x="13" y="13" width="8" height="8"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.modules}</svg>`}
const API_BASE=location.hostname==='appassets.androidplatform.net'?'http://127.0.0.1:8765':'';let token=window.Offtec?.getToken?.()||new URLSearchParams(location.search).get('token')||sessionStorage.getItem('hub-token')||'';if(token)sessionStorage.setItem('hub-token',token);let current='home',last=null,ws,apkUpload='',apkOperationId=null,rebuildPlan=null,rebuildTaskId=null,aiConfig=null,currentConversationId=null,chatTaskId=null,codexTaskId=null,codexLastRequest=null;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function nav(){$('#nav').innerHTML=pages.map(([id,title])=>`<button class="${id===current?'active':''}" data-page="${id}"><span class="ico">${icon(id==='apk'?'apk_lab':id==='dev'?'dev_studio':id==='ai'?'ai_center':id==='terminal'?'terminal':id==='security'?'netscope':id==='system'?'system_monitor':id)}</span><span>${title}</span></button>`).join('')}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3500)}
async function requestJson(url,opts={},timeout=15000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const res=await fetch(new URL(API_BASE+url,location.href),{...opts,signal:controller.signal});let data;try{data=await res.json()}catch{throw Error(`Resposta inválida do backend (HTTP ${res.status}).`)}if(!res.ok)throw Error(data.detail||`Backend respondeu HTTP ${res.status}.`);return data}catch(e){if(e.name==='AbortError')throw Error(`Tempo esgotado após ${Math.round(timeout/1000)}s.`);if(e instanceof TypeError)throw Error(`Falha de rede ao acessar o backend local (${location.origin}).`);throw e}finally{clearTimeout(timer)}}
async function api(url,opts={},timeout){if(!token)throw Error('Sessão local ausente. Reabra o aplicativo e verifique o backend.');return requestJson('/api/v1'+url,{...opts,headers:{Authorization:'Bearer '+token,...(opts.headers||{})}},timeout||((opts.method&&opts.method!=='GET')?600000:15000))}
function progress(message,active=true,percent=null){let box=$('#taskProgress');if(!box){box=document.createElement('div');box.id='taskProgress';box.className='task-progress';$('#view').prepend(box)}box.hidden=!active;if(active)box.innerHTML=`<div class="progress-head"><span class="spinner"></span><span>${esc(message)}</span>${percent==null?'':`<b>${percent}%</b>`}</div>${percent==null?'<div class="progress-track indeterminate"><i></i></div>':`<div class="progress-track"><i style="width:${percent}%"></i></div>`}`}
function connectEvents(){if(!token||ws&&(ws.readyState===WebSocket.OPEN||ws.readyState===WebSocket.CONNECTING))return;try{ws=new WebSocket(`${(API_BASE||location.origin).replace(/^http/,'ws')}/api/v1/events?token=${encodeURIComponent(token)}`);ws.onmessage=e=>{try{const d=JSON.parse(e.data);if(d.type==='progress')progress(d.message,true,d.progress??null);if(d.type==='error'){progress('',false);toast(d.message)}}catch{}};ws.onclose=()=>{ws=null}}catch{}}
function bytes(v){if(v==null)return 'Indisponível';const u=['B','KB','MB','GB','TB'];let i=0;while(v>=1024&&i<u.length-1){v/=1024;i++}return `${v.toFixed(i?1:0)} ${u[i]}`}
function badge(m){return `<span class="badge ${m.state==='ready'?'ready':''}">${m.state==='ready'?'Disponível':m.state==='not_configured'?'Não configurado':m.state==='unavailable'?'Indisponível':'Parcial'}</span>`}
function stat(l,v,s,i){return `<article class="card stat"><div class="stat-head"><span>${l}</span><span class="stat-ico">${i}</span></div><div class="stat-value">${v}</div><div class="stat-sub">${s}</div></article>`}
function moduleCard(m){return `<article class="card module-card" data-open="${esc(m.id)}"><div class="module-top"><span class="module-icon">${icon(m.id)}</span>${badge(m)}</div><h3>${esc(m.name)}</h3><p>${esc(m.description)}</p></article>`}
function renderHome(d){const s=d.system;return `<div class="grid stats">${stat('CPU',s.cpu_percent==null?'—':`${s.cpu_percent}%`,`${s.cpu_cores??'—'} núcleos detectados`,'◉')}${stat('Memória',bytes(s.ram_available_bytes),`de ${bytes(s.ram_total_bytes)} disponíveis`,'▤')}${stat('Armazenamento',bytes(s.storage_free_bytes),`livres de ${bytes(s.storage_total_bytes)}`,'▱')}${stat('Módulos',d.module_count,`${s.process_count??'—'} processos visíveis`,'▦')}${stat('Termux',s.termux?'Detectado':'Ausente',s.termux?'Ambiente local disponível':'Instale Termux','⌘')}</div><div class="grid split"><section><h2 class="section-title">Ferramentas</h2><div class="grid module-grid">${d.modules.map(moduleCard).join('')}</div></section><section><article class="card"><div class="row"><h2 class="section-title">Atividade recente</h2><button class="btn" data-page="history">Ver histórico</button></div>${d.history.length?d.history.map(x=>`<div class="history-item"><span class="history-dot" style="background:${x.status==='success'?'var(--green)':'var(--red)'}"></span><div><div class="history-name">${esc(x.module)} · ${esc(x.action)}</div><div class="history-time">${esc(new Date(x.created_at).toLocaleString())}</div></div></div>`).join(''):'<div class="empty">As operações concluídas aparecerão aqui.</div>'}<div class="notice">Android sem root pode ocultar processos, temperaturas e métricas de rede.</div></article></section></div>`}
function renderCodexPanel(){return `<section class="codex-chat"><div class="codex-head"><div><h2>Codex CLI</h2><p>Conversa processada pelo Codex real no Termux.</p></div><span id="codexActiveMethod" class="badge">Método não verificado</span></div><div class="toolbar"><button class="btn" data-action="codex-check-install">Verificar instalação</button><button class="btn" data-action="codex-check-auth">Verificar autenticação</button><button class="btn" data-action="codex-test">Testar conexão</button><select id="codexMethod" class="field" aria-label="Método Codex"><option value="auto">Automático</option><option value="main">Codex CLI principal</option><option value="fallback">Codex Fallback</option></select></div><details class="notice"><summary>Status detalhado</summary><pre id="codexStatus">Verificação pendente.</pre></details><div class="codex-controls"><span id="codexProjectStatus" class="badge">Sem projeto selecionado</span><select id="codexConversation" class="field" aria-label="Conversas Codex"></select><button class="btn" data-action="codex-new">Nova conversa</button><button class="btn" data-action="codex-delete">Excluir conversa</button><select id="codexProject" class="field" aria-label="Projeto"><option value="">Conversa sem projeto</option></select></div><div id="codexMessages" class="chat-messages codex-messages"></div><div id="codexRunState" role="status"></div><div class="codex-compose"><textarea id="codexInput" class="field" rows="2" placeholder="Pergunte ao Codex ou descreva uma tarefa de programação"></textarea><button class="btn primary" data-action="codex-send">Enviar</button><button class="btn" data-action="codex-cancel" id="codexCancel" hidden>Interromper</button></div><pre id="codexOutput" class="tool-result">Respostas são processadas pelo Codex CLI real. Alterações ficam em uma cópia isolada.</pre><button class="btn" data-action="codex-fallback" id="codexFallbackHint" hidden>Tentar a tarefa pelo Codex Fallback</button></section>`}
function renderPage(id,d){if(id==='home')return renderHome(d);if(id==='codex')return renderCodexPanel();if(id==='ai-config')return `<article class="card"><h2 class="section-title">Configuração de IA</h2><p>Cadastre cada provedor uma única vez. As ferramentas compatíveis utilizam essa configuração global; as chaves ficam no backend local.</p><div id="aiSetup"></div></article>`;if(id==='chat-ia')return `<section class="api-chat"><div class="api-chat-head"><div><h2>Chat IA</h2><span id="chatProviderStatus" class="badge">Verificando IA padrão</span></div><div class="toolbar"><select id="chatConversation" class="field" aria-label="Histórico de conversas"></select><button class="btn" data-action="chat-new">Nova conversa</button><button class="btn" data-action="chat-rename">Renomear</button><button class="btn" data-action="chat-delete">Excluir</button><select id="chatProvider" class="field" aria-label="Provedor e modelo"></select></div></div><div id="chatMessages" class="chat-messages api-messages"></div><div id="chatProgress" role="status"></div><div class="api-compose"><textarea id="chatInput" class="field" rows="2" placeholder="Escreva sua mensagem"></textarea><button class="btn primary" data-action="chat-send">Enviar</button><button class="btn" data-action="chat-cancel" id="chatCancel" hidden>Interromper</button></div></section>`;if(id==='apk')return `<article class="card"><h2 class="section-title">APK Lab · ReaDroid</h2><p>Envie um APK para inspeção estática. O arquivo é processado no backend local.</p><label class="file-drop">Selecionar APK<input id="apkFile" type="file" accept=".apk,.apks,.xapk,.zip,application/vnd.android.package-archive"></label><div id="apkName" class="tag"></div><div class="toolbar"><button class="btn primary" data-action="apk-inspect">Inspecionar APK</button><button class="btn" data-action="apk-manifest">Analisar Manifest</button><button class="btn" data-action="apk-jadx">Descompilar com JADX</button><button class="btn" data-action="apk-apktool">Extrair com Apktool</button><button class="btn" data-action="export-result">Exportar JSON</button></div><div id="result" class="tool-result">Selecione um APK para começar.</div><div class="toolbar"><button class="btn" data-action="apk-results">Ver arquivos de resultado</button></div><div id="apkResults" class="history"></div><h3 class="section-title">Reconstrução assistida (workspace isolado)</h3><p>Use uma análise concluída. O APK original e os resultados preservados não são alterados. APKs não garantem recuperação das fontes originais.</p><label>Modificação desejada<textarea id="rebuildRequest" class="field" rows="4" placeholder="Descreva o que deseja modificar nos arquivos de análise disponíveis"></textarea></label><div class="toolbar"><button class="btn" data-action="apk-rebuild-plan">Gerar plano com IA</button><button class="btn primary" data-action="apk-rebuild-apply">Confirmar plano e criar workspace</button></div><label><input id="allowRebuildBuild" type="checkbox"> Autorizar tentativa de build Gradle no workspace se houver projeto Gradle</label><div id="rebuildResult" class="tool-result">A análise será mantida separada do workspace de alterações.</div><pre id="filePreview" class="tool-result" hidden></pre></article>`;
if(id==='dev')return `<article class="card"><h2 class="section-title">Dev Studio · OffTec PortAI</h2><p>Análise de projeto e tradução revisável. A análise é somente leitura; traduções aprovadas são gravadas numa pasta externa.</p><label>Projeto existente<select id="devProject" class="field"><option value="">Selecione um projeto</option></select></label><div class="toolbar"><button class="btn primary" data-action="dev-analyze">Analisar projeto</button><button class="btn" data-action="translation-scan">Localizar textos e propor tradução</button><button class="btn" data-action="export-result">Exportar JSON</button></div><div id="result" class="tool-result">Análise real do projeto selecionado.</div><div id="translationReview"></div></article>`;
if(id==='ai')return `<article class="card"><h2 class="section-title">Programar com IA</h2><p>Usa o provedor global definido em Configuração de IA. As alterações são confirmadas e gravadas no projeto selecionado.</p><label>Projeto<select id="aiProject" class="field"><option value="">Escolher projeto autorizado</option></select></label><div class="toolbar"><input id="newProjectName" class="field" placeholder="Nome do novo projeto"><button class="btn" data-action="project-create">Criar projeto</button></div><label>O que deseja criar ou alterar?<textarea id="aiPrompt" class="field" rows="5" placeholder="Descreva a funcionalidade desejada"></textarea></label><div class="toolbar"><button class="btn primary" data-action="ai-program">Propor alterações</button><button class="btn" data-action="ai-test" id="aiTestButton">Testar projeto</button></div><div id="aiResult" class="tool-result"></div></article>`;
if(id==='terminal')return `<article class="card"><div class="row"><h2 class="section-title">Pacotes instalados no Termux</h2><button class="btn primary" data-action="packages">Atualizar inventário</button></div><p>Instalação limitada à lista fixa. A confirmação do Android/Termux é exigida antes da execução.</p><div class="package-options">${[['python','Python'],['git','Git'],['openjdk-21','OpenJDK 21'],['jadx','JADX'],['apktool','Apktool'],['aapt','AAPT / zipalign'],['apksigner','ApkSigner'],['termux-api','Termux:API CLI']].map(([id,n])=>`<label><input type="checkbox" data-package="${id}"> ${n}</label>`).join('')}</div><div class="toolbar"><button class="btn primary" data-action="install-packages">Instalar selecionados</button></div><div id="result" class="tool-result">Atualize para consultar dpkg-query.</div></article>`;
if(id==='security')return `<article class="card"><h2 class="section-title">Security Lab</h2><div class="notice">Os dados disponíveis dependem das permissões do Android. Use verificações apenas em ativos autorizados.</div><button class="btn primary" data-action="net-check">Ler conexões com NetScope</button><h3 class="section-title">Diagnóstico DNS</h3><label>Host autorizado<input id="dnsHost" class="field" placeholder="exemplo.com"></label><button class="btn" data-action="dns-lookup">Consultar DNS</button><div id="result" class="tool-result">Diagnósticos locais.</div><h3 class="section-title">Módulos de auditoria</h3><div id="securityModules">${d.modules.filter(m=>m.id==='netscope').map(m=>`<div class="history-item">${esc(m.name)} · ${esc(m.state)}</div>`).join('')}</div></article>`;
if(id==='system')return `<div class="grid stats">${stat('CPU',d.system.cpu_percent==null?'—':`${d.system.cpu_percent}%`,`Núcleos: ${d.system.cpu_cores??'—'}`,'◉')}${stat('RAM total',bytes(d.system.ram_total_bytes),`Disponível: ${bytes(d.system.ram_available_bytes)}`,'▤')}${stat('Armazenamento',bytes(d.system.storage_free_bytes),`Livre de ${bytes(d.system.storage_total_bytes)}`,'▱')}${stat('Processos',d.system.process_count??'—','Visíveis para usuário Termux','▦')}</div><article class="card"><h2 class="section-title">Ambiente e limitações</h2><div class="history-item">Termux ${d.system.termux?'detectado':'não detectado'}</div><div class="history-item">Temperatura: ${d.system.temperature_c==null?'indisponível':`${d.system.temperature_c} °C`}</div><div class="notice">Métricas limitadas aos dados acessíveis sem root.</div><button class="btn" data-action="retry">Atualizar indicadores</button></article>`;
if(id==='modules')return `<div class="module-list">${d.modules.map(m=>`<article class="card module-row"><span class="module-icon">${icon(m.id)}</span><div><h3>${esc(m.name)}</h3>${badge(m)}<p>${esc(m.description)}</p><span class="tag">Ações: ${esc(m.actions.join(', ')||'nenhuma disponível')}</span></div></article>`).join('')}</div>`;
if(id==='history')return `<article class="card"><h2 class="section-title">Histórico de operações</h2>${(d.operations||[]).map(x=>`<div class="history-item"><span class="history-dot" style="background:${x.status==='success'?'var(--green)':'var(--red)'}"></span><div>${esc(x.module)} · ${esc(x.action)} · ${esc(x.status)}<div class="history-time">${esc(new Date(x.created_at).toLocaleString())}</div></div></div>`).join('')||'<div class="empty">Ainda não há operações.</div>'}</article>`;return ''}
async function load(start=false){try{await requestJson('/api/v1/health');if(!token){const b=await requestJson('/api/v1/bootstrap',{headers:{Accept:'application/json'}});token=b.token;sessionStorage.setItem('hub-token',token)}last=await api('/dashboard');$('#view').innerHTML=renderHome(last);$('#backendTop').textContent='Backend conectado';$('#backendSide').textContent='Backend conectado';$('.head-status .pulse').classList.add('ok');connectEvents()}catch(e){$('#backendTop').textContent='Backend indisponível';$('#view').innerHTML=`<article class="card"><h2 class="section-title">Backend indisponível</h2><p role="alert">${esc(e.message)}</p><div class="toolbar"><button class="btn primary" data-action="setup-run">Iniciar / configurar no Termux</button><button class="btn" data-action="retry">Tentar novamente</button><button class="btn" data-action="setup">Instruções</button></div></article>`;if(start&&window.Offtec?.startBackend)window.Offtec.startBackend()}}
async function show(id){current=id;const page=pages.find(x=>x[0]===id)||pages.at(-1);$('#pageTitle').textContent=page[1];nav();$('#view').innerHTML='<article class="card"><span class="spinner"></span> Carregando…</article>';try{const data=id==='history'?await api('/history'):await api('/dashboard');$('#view').innerHTML=renderPage(id,data);if(id==='ai-config')await setupAi();if(id==='ai')await setupAiWorkspace();if(id==='chat-ia')await setupOfftecAI();if(id==='codex'){await codexStatus();await setupCodexChat()}if(id==='dev')await fillProjects('devProject');if(id==='apk')apkUpload='';}catch(e){$('#view').innerHTML=`<article class="card"><p role="alert">${esc(e.message)}</p><button class="btn" data-action="retry">Tentar novamente</button></article>`}}
async function fillProjects(selectId){const d=await api('/dev/projects');const el=$('#'+selectId);if(!el)return;el.innerHTML='<option value="">Selecione um projeto</option>'+d.projects.map(p=>`<option value="${esc(p.path)}">${esc(p.name)}${p.kind?` · ${esc(p.kind)}`:''}</option>`).join('')}
async function setupAiWorkspace(){const config=await api('/ai/config');await fillProjects('aiProject');$('#aiResult').textContent=config.configured?`IA global: ${config.provider} · ${config.model}`:'Configure uma IA em Configuração de IA antes de continuar.'}
async function setupAi(){
 aiConfig=await api('/ai/config');const host=$('#aiSetup');
 const cards=aiConfig.providers.map(p=>`<article class="provider-card"><div><b>${esc(p.name)}</b> · ${esc(p.provider)} · ${esc(p.model)}${p.id===aiConfig.default_id?' <span class="badge ready">Padrão</span>':''}<div class="history-time">${esc(p.base_url||'URL oficial')} · ${p.key_set?'chave protegida':'sem chave'}</div></div><div class="toolbar"><button class="btn" data-action="provider-default" data-id="${esc(p.id)}">Definir padrão</button><button class="btn" data-action="provider-test-saved" data-id="${esc(p.id)}">Testar conexão</button><button class="btn" data-action="provider-models" data-id="${esc(p.id)}">Atualizar modelos</button><button class="btn" data-action="provider-edit" data-id="${esc(p.id)}">Editar</button><button class="btn" data-action="provider-delete" data-id="${esc(p.id)}">Excluir</button></div></article>`).join('');
 host.innerHTML=`<div class="notice">${aiConfig.provider_count} provedor(es). Uma única API Key habilita todas as operações compatíveis.</div><div class="provider-list">${cards||'<div class="empty">Cadastre uma API para começar.</div>'}</div><h3 id="providerFormTitle">Adicionar provedor</h3><input id="providerId" type="hidden"><label>Nome<input id="aiName" class="field" maxlength="80" placeholder="Ex.: Minha IA"></label><label>Provedor<select id="aiProvider" class="field"><option value="gemini">Google Gemini</option><option value="groq">Groq</option><option value="openai">OpenAI</option><option value="openrouter">OpenRouter</option><option value="compatible">API compatível com OpenAI / personalizada</option></select></label><label>Modelo<select id="aiModelSelect" class="field"><option value="">Escolha um modelo</option></select></label><button class="btn" data-action="ai-load-models">Carregar modelos da API</button><label id="aiModelCustomLabel">Modelo personalizado<input id="aiModelCustom" class="field" maxlength="160" placeholder="ID do modelo fornecido pela API"></label><label>API Key<input id="aiKey" class="field" type="password" autocomplete="new-password" placeholder="Chave deste provedor"></label><label id="aiBaseLabel">URL Base<input id="aiBase" class="field" placeholder="Preenchida automaticamente para provedores conhecidos"></label><div class="toolbar"><button class="btn" data-action="ai-test-connection">Testar conexão</button><button class="btn primary" data-action="ai-save">Salvar configuração</button><button class="btn" data-action="provider-form-reset">Limpar</button></div><div id="providerFeedback" class="tool-result" aria-live="polite"></div>`;
 $('#aiModelCustomLabel').hidden=true;$('#aiBaseLabel').hidden=true;loadModelPresets();
}
function loadModelPresets(){const provider=$('#aiProvider')?.value,select=$('#aiModelSelect');if(!select)return;$('#aiModelCustomLabel').hidden=true;select.innerHTML='<option value="">Carregue a lista da API ou escolha personalizado</option><option value="__custom__">Modelo personalizado…</option>';const urls={gemini:'https://generativelanguage.googleapis.com/v1beta',groq:'https://api.groq.com/openai/v1',openai:'https://api.openai.com/v1',openrouter:'https://openrouter.ai/api/v1'};if($('#aiBase')&&urls[provider])$('#aiBase').value=urls[provider];if($('#aiBaseLabel'))$('#aiBaseLabel').hidden=provider!=='compatible'}

function selectedAiModel(){const value=$('#aiModelSelect')?.value||'';return value==='__custom__'?$('#aiModelCustom')?.value.trim()||'':value}
function resetProviderForm(){ $('#providerId').value='';$('#aiName').value='';$('#aiProvider').value='gemini';loadModelPresets();$('#aiModelCustom').value='';$('#aiKey').value='';$('#providerFormTitle').textContent='Adicionar provedor'; }
function formatChatText(value){const source=esc(value||'');return source.replace(/```([A-Za-z0-9_+.-]*)\n([\s\S]*?)```/g,(all,lang,code)=>`<pre class="chat-code"><button class="btn" data-copy="${esc(code)}">Copiar código</button><code>${code}</code></pre>`).replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/\n/g,'<br>')}
function renderChatMessages(conversation){currentConversationId=conversation.id;$('#chatConversation').value=conversation.id;$('#chatMessages').innerHTML=conversation.messages.map(m=>`<article class="chat-message ${m.role==='user'?'user':'assistant'}"><b>${m.role==='user'?'Você':m.role==='tool'?'Ferramenta executada':'OFFTEC AI'}</b><div>${formatChatText(m.content)}</div>${m.meta?.pending_tools?`<div class="notice">Ação pendente: ${esc(JSON.stringify(m.meta.pending_tools))}<button class="btn primary" data-action="chat-confirm-tool" data-message="${esc(m.id)}">Confirmar execução</button></div>`:''}</article>`).join('');$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight}
async function refreshConversations(selected=currentConversationId){const data=await api('/ai/conversations');$('#chatConversation').innerHTML=data.conversations.map(c=>`<option value="${esc(c.id)}">${esc(c.title)} (${c.message_count})</option>`).join('')||'<option value="">Sem conversas</option>';if(selected&&data.conversations.some(c=>c.id===selected)){$('#chatConversation').value=selected;renderChatMessages(await api(`/ai/conversations/${selected}`))}else if(data.conversations.length){renderChatMessages(await api(`/ai/conversations/${data.conversations[0].id}`))}else $('#chatMessages').innerHTML='<div class="empty">Inicie uma conversa para trabalhar com as ferramentas.</div>'}
async function codexStatus(){const d=await api('/codex/status');const view={version:d.version,active_method:d.active_method,authenticated:d.authenticated,reason:d.reason,methods:d.methods?.map(m=>({id:m.id,label:m.label,installed:m.installed,functional:m.functional,authenticated:m.authenticated,version:m.version,features:m.features,reason:m.reason,auth_detail:m.auth_detail}))};$('#codexStatus').textContent=JSON.stringify(view,null,2);$('#codexActiveMethod').textContent=d.active_method?`Ativo: ${d.methods.find(m=>m.id===d.active_method)?.label||d.active_method}`:'Nenhum método funcional';return d}
let codexConversationId=null;
function renderCodexMessages(c){codexConversationId=c.id;$('#codexConversation').value=c.id;$('#codexProjectStatus').textContent=c.project_name?`Workspace: ${c.project_name}`:'Conversa sem projeto · somente leitura';$('#codexMessages').innerHTML=c.messages.map(m=>`<article class="chat-message ${m.role==='user'?'user':'assistant'}"><b>${m.role==='user'?'Você':m.role==='tool'?'OFFTEC HUB':`Codex CLI · ${esc(m.meta?.method||'real')}`}</b><div>${formatChatText(m.content)}</div>${m.meta?.files?.length?`<div class="notice">Arquivos alterados na cópia:<br>${m.meta.files.map(x=>esc(x)).join('<br>')}${c.has_project?`<button class="btn primary" data-action="codex-apply" data-conversation="${esc(c.id)}">Revisar e aplicar ao projeto</button>`:''}</div>`:''}${m.meta?.apply_result&&m.meta?.applied?.length?`<div class="notice">Arquivos aplicados com backup: ${m.meta.applied.map(x=>esc(x)).join(', ')}</div>`:''}${m.meta?.stderr?`<details><summary>Detalhes da falha</summary><pre>${esc(m.meta.stderr)}</pre></details>`:''}</article>`).join('')||'<div class="empty">Faça uma pergunta ao Codex. Para alterar um projeto, selecione-o antes de iniciar a conversa.</div>';$('#codexMessages').scrollTop=$('#codexMessages').scrollHeight}
async function refreshCodexConversations(selected=codexConversationId){const d=await api('/codex/conversations');$('#codexConversation').innerHTML=d.conversations.map(c=>`<option value="${esc(c.id)}">${esc(c.title)} · ${c.message_count}</option>`).join('')||'<option value="">Sem conversas</option>';if(selected&&d.conversations.some(c=>c.id===selected)){renderCodexMessages(await api(`/codex/conversations/${selected}`));return}if(d.conversations.length){renderCodexMessages(await api(`/codex/conversations/${d.conversations[0].id}`));return}codexConversationId=null;$('#codexMessages').innerHTML='<div class="empty">Faça uma pergunta ao Codex. Para alterar um projeto, selecione-o antes de iniciar a conversa.</div>'}
async function setupCodexChat(){await fillProjects('codexProject');await refreshCodexConversations()}
async function newCodexConversation(){const path=$('#codexProject').value,method=$('#codexMethod').value;const body={title:'Nova conversa Codex',method};if(path)body.path=path;const c=await api('/codex/conversations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});codexConversationId=c.id;await refreshCodexConversations(c.id);$('#codexInput').focus()}
async function sendCodexMessage(){const message=$('#codexInput').value.trim();if(!message)throw Error('Escreva uma mensagem para o Codex.');if(!codexConversationId)await newCodexConversation();const conversation=await api(`/codex/conversations/${codexConversationId}`);if(conversation.has_project&&!confirm('O Codex poderá alterar somente uma cópia isolada do projeto selecionado. Prosseguir?'))return;$('#codexInput').value='';$('#codexRunState').textContent='Enviando ao Codex CLI real…';const d=await api('/codex/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({conversation_id:codexConversationId,message,confirmed:!!conversation.has_project,method:$('#codexMethod').value})},30000);codexTaskId=d.task_id;codexLastRequest={kind:'chat',conversation_id:codexConversationId,prompt:message,method:$('#codexMethod').value};$('#codexCancel').hidden=false;while(true){await new Promise(resolve=>setTimeout(resolve,700));const state=await api(`/codex/tasks/${codexTaskId}`,{},15000);$('#codexRunState').textContent=state.status==='running'?`Codex executando · método ${state.method||'automático'} · ${state.events?.length||0} eventos recebidos`:state.status==='cancelling'?'Interrompendo a tarefa…':state.status==='error'?`Falha: ${state.error||'erro do CLI'}`:'';if(state.stdout_tail)$('#codexOutput').textContent=state.stdout_tail;showCodexTask(state);if(['success','error','cancelled'].includes(state.status)){codexTaskId=null;$('#codexCancel').hidden=true;$('#codexRunState').textContent=state.status==='success'?'Resposta recebida do Codex real.':`Execução ${state.status}: ${state.error||''}`;await new Promise(resolve=>setTimeout(resolve,400));await refreshCodexConversations(codexConversationId);return}}}
function showCodexTask(state){const running=!['success','error','cancelled'].includes(state.status);const result=state.result||{};const view={status:state.status,task_id:state.task_id,method:state.method,events:state.events||result.events||[],stdout:state.stdout_tail||result.stdout_tail||'',stderr:state.stderr_tail||result.stderr_tail||'',response:result.response||'',files:result.files||[],errors:result.errors||state.error||null,workspace:result.workspace||null,returncode:result.returncode??null};$('#codexOutput').textContent=state.status==='error'?JSON.stringify(view,null,2):(state.stdout_tail||result.response||`Codex ${state.status}`);$('#codexCancel').hidden=!running;$('#codexFallbackHint').hidden=running||state.status!=='error'||!codexLastRequest||codexLastRequest.method==='fallback'}
async function watchCodexTask(task){codexTaskId=task.task_id;showCodexTask({...task,status:'running'});while(true){await new Promise(resolve=>setTimeout(resolve,700));const state=await api(`/codex/tasks/${codexTaskId}`,{},15000);showCodexTask(state);if(['success','error','cancelled'].includes(state.status)){codexTaskId=null;return state}progress(state.status==='cancelling'?'Encerrando processo Codex…':`Codex (${state.method||'selecionando método'}) trabalhando na cópia isolada`)}}

async function setupOfftecAI(){const config=await api('/ai/config');$('#chatProviderStatus').textContent=config.configured?`Padrão: ${config.provider} · ${config.model} (não testado)`:'Nenhum provedor configurado';$('#chatProviderStatus').className=`badge ${config.configured?'ready':''}`;$('#chatProvider').innerHTML=config.providers.map(p=>`<option value="${esc(p.id)}" ${p.id===config.default_id?'selected':''}>${esc(p.name)} · ${esc(p.model)}</option>`).join('')||'<option value="">Configure uma API em Configuração de IA</option>';await refreshConversations()}
function selectedProject(){return $('#aiProject')?.value||''}
function setResult(value,selector='#result'){const el=$(selector);if(el)el.textContent=typeof value==='string'?value:JSON.stringify(value,null,2);window.lastResult=value}
async function runAction(action,b){const result=()=>$('#result');if(action.startsWith('apk-')&&action!=='apk-results'){if(!apkUpload)throw Error('Selecione um arquivo APK e aguarde o envio antes de analisar.');const op=action.slice(4);progress('Analisando APK no ReaDroid');const d=await api('/apk/operations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({upload_id:apkUpload,action:op})},900000);progress('',false);apkOperationId=d.operation_id;rebuildPlan=null;setResult(d.result);return}
if(action==='apk-results'){const d=await api('/apk/results');$('#apkResults').innerHTML=d.files.map(f=>`<button class="history-item result-file" data-file="${esc(f.id)}">${esc(f.area)} · ${esc(f.path)} · ${bytes(f.size_bytes)}</button>`).join('')||'<div class="empty">Nenhum arquivo de resultado ainda.</div>';return}
if(action==='apk-rebuild-plan'){if(!apkOperationId)throw Error('Execute primeiro uma análise ReaDroid deste APK.');const request=$('#rebuildRequest').value.trim();if(!request)throw Error('Descreva a modificação desejada.');progress('Enviando dados reais da análise para planejar alterações');const d=await api('/apk/rebuild/plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation_id:apkOperationId,request})},180000);progress('',false);rebuildPlan=d;$('#rebuildResult').textContent=`Plano ${d.plan_id}:\n${d.plan}\n\nArquivos disponíveis: ${d.available_files.map(f=>f.path).join(', ')||'nenhum arquivo extraído'}\nFontes originais recuperadas: NÃO\nLimitações: ${d.limitations.join('; ')}`;return}
if(action==='apk-rebuild-apply'){if(!rebuildPlan)throw Error('Gere um plano antes de confirmar.');if(!confirm('Criar cópia isolada e aplicar o plano apresentado?'))return;progress('Criando workspace separado e aplicando alterações');const d=await api('/apk/rebuild/apply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({plan_id:rebuildPlan.plan_id,request:$('#rebuildRequest').value.trim(),confirmed:true,allow_build:$('#allowRebuildBuild').checked})},30000);rebuildTaskId=d.task_id;$('#rebuildResult').innerHTML=`Tarefa ${esc(d.task_id)} em andamento. <button class="btn" data-action="apk-rebuild-cancel">Cancelar operação</button>`;while(true){await new Promise(resolve=>setTimeout(resolve,1000));const state=await api(`/apk/rebuild/tasks/${rebuildTaskId}`,{},15000);if(state.status==='completed'||state.status==='error'||state.status==='cancelled'){progress('',false);$('#rebuildResult').textContent=JSON.stringify(state,null,2);break}progress(state.status==='cancelling'?'Cancelamento solicitado; aguardando término da etapa atual':'Criando e validando workspace');}return}
if(action==='apk-rebuild-cancel'){if(!rebuildTaskId)throw Error('Nenhuma reconstrução está em andamento.');const d=await api(`/apk/rebuild/tasks/${rebuildTaskId}/cancel`,{method:'POST'});$('#rebuildResult').textContent=`Status: ${d.status}. O provedor pode terminar a chamada HTTP atual antes de confirmar o cancelamento.`;return}
if(action==='dev-analyze'){const path=$('#devProject')?.value;if(!path)throw Error('Escolha um projeto na lista.');const d=await api('/dev/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path,action:'analyze_project'})});setResult(d.result);return}
if(action==='translation-scan'){const path=$('#devProject')?.value;if(!path)throw Error('Selecione um projeto.');progress('Localizando textos e consultando o provedor configurado');const d=await api('/dev/translation/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path,source_language:'en',targets:['pt-BR']})},300000);progress('',false);window.translationSession=d;$('#result').textContent=`${d.entry_count} entradas analisadas · provedor ${d.provider}`;$('#translationReview').innerHTML=`<div class="notice">${esc(d.note)}${d.truncated?' Prévia truncada.':''}</div>${d.entries.map(e=>`<label class="history-item"><input type="checkbox" data-entry="${esc(e.entry_id)}" ${Object.keys(e.translations||{}).length?'':'disabled'}>${esc(e.path)} · ${esc(e.key)} · ${esc(e.source)}<br>${esc(JSON.stringify(e.translations||{}))}</label>`).join('')}<p class="notice">A tradução será criada automaticamente em uma nova pasta, sem alterar o projeto original.</p><button class="btn primary" data-action="translation-apply">Aplicar selecionadas</button><div id="translationResult" class="tool-result"></div>`;return}
if(action==='translation-apply'){const ids=[...document.querySelectorAll('[data-entry]:checked')].map(x=>x.dataset.entry);if(!ids.length)throw Error('Selecione ao menos uma tradução proposta.');const d=await api('/dev/translation/apply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session_id:window.translationSession.session_id,selected_entries:ids,targets:['pt-BR']})});setResult(d,'#translationResult');return}
if(action==='packages'){const d=await api('/terminal/packages');setResult(d.available?{count:d.count,packages:d.packages}:d);return}
if(action==='install-packages'){const packages=[...document.querySelectorAll('[data-package]:checked')].map(x=>x.dataset.package);if(!packages.length)throw Error('Selecione pelo menos um pacote.');if(!confirm(`Instalar ${packages.join(', ')} no Termux?`))return;setResult(await api('/terminal/install',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({packages})},900000));return}
if(action==='net-check'){setResult(await api('/security/network',{},30000));return}
if(action==='dns-lookup'){const hostname=$('#dnsHost').value.trim();if(!hostname)throw Error('Informe um host.');setResult(await api('/security/dns',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({hostname})},30000));return}
if(action==='ai-load-models'){const d=await api('/ai/providers/models',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:$('#aiProvider').value,api_key:$('#aiKey').value,base_url:$('#aiBase').value})},30000);const select=$('#aiModelSelect');select.innerHTML='<option value="">Selecione um modelo retornado pela API</option>'+d.models.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')+'<option value="__custom__">Modelo personalizado…</option>';$('#providerFeedback').textContent=`${d.models.length} modelos disponíveis para ${d.provider}.`;toast('Lista de modelos atualizada.');return}
if(action==='ai-save'){const id=$('#providerId').value,body={name:$('#aiName').value,provider:$('#aiProvider').value,model:selectedAiModel(),api_key:$('#aiKey').value,base_url:$('#aiBase').value};if(!body.name||!body.model||(!id&&!body.api_key))throw Error('Informe nome, modelo e chave para um provedor novo.');const d=await api(id?`/ai/providers/${id}`:'/ai/providers',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});aiConfig=d;$('#aiKey').value='';toast('Provedor salvo no backend.');await setupAi();return}
if(action==='provider-form-reset'){resetProviderForm();return}
if(action==='provider-models'){const d=await api(`/ai/providers/${b.dataset.id}/models`,{},30000);const p=aiConfig.providers.find(x=>x.id===b.dataset.id);if(!p)throw Error('Provedor não encontrado.');$('#providerId').value=p.id;$('#aiName').value=p.name;$('#aiProvider').value=p.provider;$('#aiBase').value=p.base_url;$('#aiKey').value='';$('#providerFormTitle').textContent=`Editar ${p.name}`;const select=$('#aiModelSelect');select.innerHTML='<option value="">Selecione um modelo</option>'+d.models.map(x=>`<option value="${esc(x)}" ${x===p.model?'selected':''}>${esc(x)}</option>`).join('')+'<option value="__custom__">Modelo personalizado…</option>';$('#aiModelCustomLabel').hidden=true;$('#providerFeedback').textContent=`${d.models.length} modelos disponíveis. Escolha um e salve para atualizar.`;$('#providerFormTitle').scrollIntoView({behavior:'smooth'});return}
if(action==='provider-edit'){const p=aiConfig.providers.find(x=>x.id===b.dataset.id);if(!p)throw Error('Provedor não encontrado.');$('#providerId').value=p.id;$('#aiName').value=p.name;$('#aiProvider').value=p.provider;loadModelPresets();if([...$('#aiModelSelect').options].some(o=>o.value===p.model))$('#aiModelSelect').value=p.model;else{$('#aiModelSelect').value='__custom__';$('#aiModelCustomLabel').hidden=false;$('#aiModelCustom').value=p.model;}$('#aiBase').value=p.base_url;$('#aiKey').value='';$('#providerFormTitle').textContent=`Editar ${p.name}`;$('#providerFormTitle').scrollIntoView({behavior:'smooth'});return}
if(action==='provider-default'){aiConfig=await api(`/ai/default/${b.dataset.id}`,{method:'PUT'});toast('Provedor padrão atualizado.');await setupAi();return}
if(action==='provider-delete'){const p=aiConfig.providers.find(x=>x.id===b.dataset.id);if(!p||!confirm(`Remover a configuração ${p.name}?`))return;aiConfig=await api(`/ai/providers/${b.dataset.id}`,{method:'DELETE'});toast('Configuração removida.');await setupAi();return}
if(action==='provider-test-saved'){const d=await api('/ai/providers/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider_id:b.dataset.id})},30000);$('#providerFeedback').textContent=d.message;toast(d.connected?'Conexão confirmada.':d.message);return}
if(action==='ai-test-connection'){const id=$('#providerId').value;const body=id?{provider_id:id}:{provider:$('#aiProvider').value,model:selectedAiModel(),api_key:$('#aiKey').value,base_url:$('#aiBase').value};const d=await api('/ai/providers/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)},30000);$('#providerFeedback').textContent=d.message;toast(d.connected?'Conexão confirmada.':d.message);return}
if(action==='project-create'){const name=$('#newProjectName').value.trim();if(!name)throw Error('Informe o nome do projeto.');const d=await api('/dev/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});await fillProjects('aiProject');$('#aiProject').value=d.path;$('#newProjectName').value='';toast('Projeto criado.');return}
if(action==='ai-program'){const path=selectedProject(),prompt=$('#aiPrompt').value.trim();if(!path||!prompt)throw Error('Selecione o projeto e descreva a tarefa.');if(!confirm('Autorizar o provedor a propor e gravar alterações nos arquivos deste projeto?'))return;progress('Lendo os arquivos e solicitando alterações ao provedor de IA');$('#aiTestButton').hidden=true;try{const d=await api('/ai/program',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path,prompt,confirmed:true})},600000);progress('',false);setResult(d,'#aiResult');$('#aiTestButton').hidden=false}catch(e){progress('',false);throw e}return}
if(action==='ai-test'){const path=selectedProject();if(!path)throw Error('Selecione um projeto.');if(!confirm('Executar os testes reconhecidos neste projeto? Os testes podem executar código do próprio projeto.'))return;progress('Executando testes reconhecidos do projeto');const d=await api('/ai/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path,confirmed:true})},360000);progress('',false);setResult(d,'#aiResult');if(d.tested&&!d.passed){$('#aiPrompt').value=`Corrija os erros encontrados nos testes abaixo. Preserve o comportamento existente.\n\n${JSON.stringify(d.results)}`;toast('Testes falharam. Descreva/corrija e toque em PROGRAMAR para solicitar ajustes.')}else if(!d.tested)toast(d.message);return}
if(action==='codex-check'||action==='codex-check-install'||action==='codex-check-auth'){await codexStatus();return}
if(action==='codex-new'){await newCodexConversation();return}
if(action==='codex-send'){await sendCodexMessage();return}
if(action==='codex-delete'){if(!codexConversationId||!confirm('Excluir esta conversa e seu histórico?'))return;await api(`/codex/conversations/${codexConversationId}`,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmed:true})});codexConversationId=null;await refreshCodexConversations();return}
if(action==='codex-apply'){const conversationId=b.dataset.conversation;if(!confirm('Aplicar os arquivos alterados no projeto selecionado? Arquivos existentes receberão cópia de segurança; conflitos interrompem a aplicação.'))return;const d=await api(`/codex/conversations/${conversationId}/apply`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmed:true})},60000);await refreshCodexConversations(conversationId);toast(d.applied?.length?`${d.applied.length} arquivo(s) aplicado(s) com backup.`:d.message);return}
if(action==='codex-test'){const path=$('#codexProject')?.value,method=$('#codexMethod').value;if(!confirm('Testar a conexão real do Codex numa cópia temporária, com sandbox somente leitura?'))return;codexLastRequest={kind:'test',path,method};const d=await api('/codex/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:path||undefined,prompt:'test',confirmed:true,method})},30000);await watchCodexTask(d);progress('',false);await codexStatus();return}
if(action==='codex-run'){const path=$('#codexProject')?.value,prompt=$('#codexInput')?.value.trim(),method=$('#codexMethod').value;if(!prompt)throw Error('Informe a tarefa.');if(!confirm('Codex poderá editar somente a cópia isolada deste projeto. Prosseguir?'))return;codexLastRequest={kind:'run',path,prompt,method};progress('Preparando cópia e executando Codex com as aprovações padrão');const d=await api('/codex/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:path||undefined,prompt,confirmed:true,method})},30000);await watchCodexTask(d);progress('',false);return}
if(action==='codex-fallback'){if(!codexLastRequest)throw Error('Não há tarefa para repetir pelo fallback.');if(!confirm('Tentar novamente pelo Codex Fallback? A execução altera apenas uma cópia isolada.'))return;const req={...codexLastRequest,method:'fallback'};codexLastRequest=req;if(req.kind==='chat'){const d=await api('/codex/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({conversation_id:req.conversation_id,message:req.prompt,confirmed:true,retry:true,method:'fallback'})},30000);codexTaskId=d.task_id;$('#codexCancel').hidden=false;while(true){await new Promise(resolve=>setTimeout(resolve,700));const state=await api(`/codex/tasks/${codexTaskId}`,{},15000);showCodexTask(state);if(['success','error','cancelled'].includes(state.status)){codexTaskId=null;$('#codexCancel').hidden=true;await new Promise(resolve=>setTimeout(resolve,400));await refreshCodexConversations(req.conversation_id);break}}return}const endpoint=req.kind==='test'?'/codex/test':'/codex/run';const d=await api(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:req.path,prompt:req.prompt||'test',confirmed:true,method:'fallback'})},30000);await watchCodexTask(d);progress('',false);return}
if(action==='codex-cancel'){if(!codexTaskId)throw Error('Nenhuma tarefa Codex está em andamento.');const d=await api(`/codex/tasks/${codexTaskId}/cancel`,{method:'POST'});$('#codexOutput').textContent=`${d.status}: encerramento solicitado`;return}
if(action==='chat-test-provider'){const id=$('#chatProvider').value;if(!id)throw Error('Configure e selecione um provedor.');$('#chatProviderStatus').textContent='Testando conexão real…';const d=await api('/ai/providers/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider_id:id})},30000);$('#chatProviderStatus').textContent=d.connected?`Conectado: ${d.provider} · ${d.model}`:`Falha: ${d.message}`;toast(d.message);return}
if(action==='chat-new'){const d=await api('/ai/conversations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:'Nova conversa'})});await refreshConversations(d.id);$('#chatInput').focus();return}
if(action==='chat-rename'){if(!currentConversationId)throw Error('Selecione uma conversa.');const title=prompt('Novo nome para a conversa:');if(!title?.trim())return;await api(`/ai/conversations/${currentConversationId}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:title.trim()})});await refreshConversations();return}
if(action==='chat-delete'){if(!currentConversationId||!confirm('Excluir esta conversa e seu histórico?'))return;await api(`/ai/conversations/${currentConversationId}`,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmed:true})});currentConversationId=null,chatTaskId=null,codexTaskId=null;await refreshConversations();return}
if(action==='chat-send'){const message=$('#chatInput').value.trim();if(!message)throw Error('Digite uma mensagem.');if(!currentConversationId){const d=await api('/ai/conversations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({})});currentConversationId=d.id}$('#chatProgress').innerHTML='Enviando ao provedor…';const d=await api('/ai/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({conversation_id:currentConversationId,message})},30000);chatTaskId=d.task_id;$('#chatProgress').innerHTML=`Gerando resposta… <button class="btn" data-action="chat-cancel">Cancelar</button>`;while(true){await new Promise(resolve=>setTimeout(resolve,700));const state=await api(`/ai/chat/tasks/${chatTaskId}`,{},15000);if(['completed','cancelled','error'].includes(state.status)){chatTaskId=null,codexTaskId=null;$('#chatProgress').textContent=state.status==='error'?`Falha: ${state.error}`:'';await refreshConversations(d.conversation_id);break}}return}
if(action==='chat-cancel'){if(!chatTaskId)throw Error('Nenhuma geração está em andamento.');const d=await api(`/ai/chat/tasks/${chatTaskId}/cancel`,{method:'POST'});$('#chatProgress').textContent=`${d.status}: cancelamento cooperativo solicitado`;return}
if(action==='chat-confirm-tool'){if(!currentConversationId||!confirm('Executar no backend a operação e os parâmetros apresentados?'))return;const d=await api(`/ai/conversations/${currentConversationId}/confirm-tool`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message_id:b.dataset.message,confirmed:true})},60000);renderChatMessages(d);return}
if(action==='export-result'){const json=JSON.stringify(window.lastResult??{message:'Nenhum resultado disponível'},null,2);if(window.Offtec?.saveJson)window.Offtec.saveJson(json);else{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([json],{type:'application/json'}));a.download='offtec-hub-result.json';a.click();URL.revokeObjectURL(a.href)}return}
if(action==='retry'){if(current==='home')await load();else await show(current);return}
if(action==='setup-run'){window.Offtec?.startTermuxSetup?.();toast('Solicitação de configuração enviada ao Termux.');return}
if(action==='setup'){toast('No Termux, execute bash ~/HUB/termux/install.sh');return}
}
document.addEventListener('click',async e=>{const copy=e.target.closest('[data-copy]');if(copy){try{await navigator.clipboard.writeText(copy.dataset.copy);toast('Código copiado.')}catch{toast('Não foi possível copiar neste WebView.')}return}const page=e.target.closest('[data-page]');if(page){show(page.dataset.page);return}const card=e.target.closest('[data-open]');if(card){const id=({apk_lab:'apk',dev_studio:'dev',ai_center:'ai',terminal:'terminal',netscope:'security',system_monitor:'system'})[card.dataset.open];if(id)show(id);return}const file=e.target.closest('[data-file]');if(file){try{const d=await api(`/apk/results/${file.dataset.file}`);const p=$('#filePreview');p.hidden=false;p.textContent=d.binary?`Arquivo binário · ${bytes(d.size_bytes)}`:d.content}catch(err){toast(err.message)}return}const b=e.target.closest('[data-action]');if(!b)return;try{b.disabled=true;await runAction(b.dataset.action,b)}catch(err){console.error(err);if(b.dataset.action.startsWith('codex-')&&$('#codexOutput')){$('#codexOutput').textContent=err.message;if(codexLastRequest&&codexLastRequest.method!=='fallback')$('#codexFallbackHint').hidden=false}else{const dest=$('#aiResult')&&!$('#aiWorkspace').hidden?'#aiResult':'#result';if($(dest))setResult(err.message,dest);else toast(err.message)}}finally{b.disabled=false}});
document.addEventListener('change',async e=>{if(e.target.id==='chatConversation'&&e.target.value){currentConversationId=e.target.value;await refreshConversations(currentConversationId)}if(e.target.id==='codexConversation'&&e.target.value){codexConversationId=e.target.value;await refreshCodexConversations(codexConversationId)}if(e.target.id==='codexProject'&&codexConversationId){toast('A escolha de projeto vale para uma nova conversa Codex.');}if(e.target.id==='chatProvider'&&e.target.value){try{const c=await api(`/ai/default/${e.target.value}`,{method:'PUT'});$('#chatProviderStatus').textContent=`Padrão: ${c.provider} · ${c.model} (não testado)`;toast('Provedor e modelo padrão atualizados.')}catch(err){toast(err.message)}}if(e.target.id==='apkFile'){const f=e.target.files?.[0];if(!f)return;$('#apkName').textContent=`${f.name} · ${bytes(f.size)}`;$('#result').textContent='Enviando arquivo ao backend…';progress(`Enviando ${f.name}`);try{const form=new FormData();form.append('file',f,f.name);const d=await api('/files/apk',{method:'POST',body:form},600000);apkUpload=d.upload_id;progress('',false);$('#result').textContent='APK enviado. Escolha a análise desejada.'}catch(err){progress('',false);$('#result').textContent=err.message}}if(e.target.id==='aiProvider')loadModelPresets();if(e.target.id==='aiModelSelect'){const custom=e.target.value==='__custom__';$('#aiModelCustomLabel').hidden=!custom;}if(e.target.id==='aiProvider')$('#aiBaseLabel').hidden=e.target.value!=='compatible';if(e.target.id==='aiActive'){try{aiConfig=await api(`/ai/active/${e.target.value}`,{method:'PUT'});toast('Provedor ativo atualizado.')}catch(err){toast(err.message)}}if(e.target.name==='aiChoice')$('#aiProviderForm').hidden=e.target.value!=='new'});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&e.target.id==='chatInput'){e.preventDefault();document.querySelector('[data-action=chat-send]')?.click()}if(e.key==='Enter'&&!e.shiftKey&&e.target.id==='codexInput'){e.preventDefault();document.querySelector('[data-action=codex-send]')?.click()}});window.addEventListener('error',e=>console.error('[OFFTEC HUB] Erro JavaScript:',e.message,e.filename,e.lineno));window.addEventListener('unhandledrejection',e=>{console.error('[OFFTEC HUB]',e.reason);toast(e.reason?.message||'Erro inesperado')});nav();$('#view').innerHTML='<article class="card">Conectando ao backend local…</article>';load(true);setInterval(()=>{if(current==='home')load(false)},15000);
